<?php require_once __DIR__.'/includes/bootstrap.php';require_verified();$staff=in_array(current_user()['role'],['admin','librarian'],true);$q=trim($_GET['q']??'');$cat=(int)($_GET['category_id']??0);$sql='SELECT b.*,c.name category_name FROM books b LEFT JOIN categories c ON c.id=b.category_id WHERE b.is_archived=0';$types='';$p=[];if($q!==''){$sql.=' AND (b.title LIKE ? OR b.author LIKE ? OR b.isbn LIKE ?)';$like="%$q%";$types.='sss';array_push($p,$like,$like,$like);}if($cat){$sql.=' AND b.category_id=?';$types.='i';$p[]=$cat;}$sql.=' ORDER BY b.title';$s=$conn->prepare($sql);if($types)$s->bind_param($types,...$p);$s->execute();$rows=$s->get_result();$cats=$conn->query('SELECT id,name FROM categories ORDER BY name');page_header('Books');?><div class="page-heading"><div><p class="eyebrow">CATALOG</p><h1>Books</h1><p class="muted">Search books and request an available copy.</p></div><?php if($staff):?><a class="btn" href="book_form.php">+ Add book</a><?php endif;?></div><form class="filter-bar"><input name="q" value="<?=e($q)?>" placeholder="Search title, author, ISBN"><select name="category_id"><option value="0">All categories</option><?php while($c=$cats->fetch_assoc()):?><option value="<?=$c['id']?>" <?=$cat===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endwhile;?></select><button class="btn">Search</button><a class="btn secondary" href="books.php">Reset</a></form><div class="table-wrap panel"><table><thead><tr><th>Title / Author</th><th>Category</th><th>ISBN</th><th>Available</th><th>Actions</th></tr></thead><tbody><?php if($rows->num_rows):while($b=$rows->fetch_assoc()):?><tr><td><strong><?=e($b['title'])?></strong><div class="muted small"><?=e($b['author'])?></div></td><td><?=e($b['category_name']??'Uncategorized')?></td><td><?=e($b['isbn']??'—')?></td><td><?=$b['available_copies']?> / <?=$b['total_copies']?></td><td class="actions"><?php if(current_user()['role']==='member'):?><?php if((int)$b['available_copies']>0):?><form method="post" action="actions/borrow_request.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="book_id" value="<?=$b['id']?>"><button class="btn small-btn">Borrow request</button></form><?php endif;?><form method="post" action="actions/reservation_request.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="book_id" value="<?=$b['id']?>"><button class="btn secondary small-btn">Reserve</button></form><?php endif;?><?php if($staff):?><a class="btn secondary small-btn" href="book_form.php?id=<?=$b['id']?>">Edit</a><form method="post" action="actions/book_delete.php" data-confirm="Archive this book?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="btn danger small-btn">Archive</button></form><?php endif;?></td></tr><?php endwhile;else:?><tr><td colspan="5" class="empty">No matching books found.</td></tr><?php endif;?></tbody></table></div><?php page_footer();?>